            accept: [['bank|government|compan|promot|advert|push'], ['as much|also|too|not only|as well|just as|rather than|other']],
            reject: [{ re: 'appears at once|both accounts', hint: 'That makes Facet A stronger. Give a second reason for the speed.' },
              { re: 'nobody|under the age', hint: 'Too absolute, and a guess you cannot check.' },
              { re: '\\bfee\\b|traders', hint: 'A fee would slow the change down. Give a second reason for the speed.' },
              { re: 'change were pushed', hint: 'One change: check the verb.' }],
