            reject: [{ re: 'though$', hint: 'Check the spelling of the last word.' },
              { re: '^it operate\\b', hint: 'The subject is "It": check the verb.' },
              { re: 'as a result|therefore', hint: 'This is not a result: it explains how people are shut out.' }],
